  <script>
    // Hero carousel
    let heroIdx = 0;
    const heroSlides = document.getElementById('heroSlides');
    const heroDots = document.querySelectorAll('.carousel-dot');
    const totalSlides = 5;

    function goToHeroSlide(n) {
      heroIdx = (n + totalSlides) % totalSlides;
      heroSlides.style.transform = `translateX(-${heroIdx * 100}%)`;
      heroDots.forEach((d, i) => d.classList.toggle('active', i === heroIdx));
    }

    document.getElementById('heroPrev').addEventListener('click', () => goToHeroSlide(heroIdx - 1));
    document.getElementById('heroNext').addEventListener('click', () => goToHeroSlide(heroIdx + 1));
    heroDots.forEach(d => d.addEventListener('click', () => goToHeroSlide(+d.dataset.idx)));

    // Auto-advance hero
    let heroTimer = setInterval(() => goToHeroSlide(heroIdx + 1), 5000);
    document.querySelector('.hero-carousel').addEventListener('mouseenter', () => clearInterval(heroTimer));
    document.querySelector('.hero-carousel').addEventListener('mouseleave', () => {
      heroTimer = setInterval(() => goToHeroSlide(heroIdx + 1), 5000);
    });

    // New courses horizontal carousel
    const newCoursesEl = document.getElementById('newCourses');
    document.getElementById('newPrev').addEventListener('click', () => {
      newCoursesEl.scrollBy({ left: -270, behavior: 'smooth' });
    });
    document.getElementById('newNext').addEventListener('click', () => {
      newCoursesEl.scrollBy({ left: 270, behavior: 'smooth' });
    });
  </script>
