/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; color: #171717; background: #fff; line-height: 1.5; }
ul { list-style: none; }
a { text-decoration: none; color: inherit; }
button { font-family: inherit; cursor: pointer; }

/* ── Promo Banner ── */
.promo-banner {
  background: #F02D00; color: #fff; padding: 10px 16px;
  display: flex; align-items: center; justify-content: center; gap: 12px;
  position: relative; font-size: 14px; font-weight: 500;
}
.promo-banner.hidden { display: none; }
.promo-content { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: center; }
.promo-fire { font-size: 16px; }
.countdown { font-weight: 800; font-size: 16px; font-variant-numeric: tabular-nums; }
.promo-close {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  background: none; border: none; color: #fff; font-size: 22px; line-height: 1;
  opacity: 0.8; transition: opacity 0.2s;
}
.promo-close:hover { opacity: 1; }

/* ── Header ── */
.header {
  background: #fff; border-bottom: 1px solid #eee;
  position: sticky; top: 0; z-index: 100;
  box-shadow: 0 1px 6px rgba(0,0,0,0.06);
}
.header-inner {
  max-width: 1200px; margin: 0 auto; padding: 0 24px;
  height: 64px; display: flex; align-items: center; gap: 24px;
}
.logo { font-size: 20px; font-weight: 900; color: #171717; flex-shrink: 0; }
.logo span { color: #F02D00; }
.nav-links { display: flex; gap: 4px; }
.nav-link { font-size: 14px; font-weight: 500; color: #333; padding: 6px 12px; border-radius: 6px; transition: background 0.15s, color 0.15s; }
.nav-link:hover, .nav-link.active { background: #f5f5f5; color: #171717; }
.nav-plus { color: #F02D00 !important; font-weight: 700; }
.nav-plus:hover { background: rgba(240,45,0,0.08) !important; }
.header-search { flex: 1; max-width: 400px; position: relative; }
.search-input { width: 100%; padding: 8px 36px 8px 14px; border: 1.5px solid #e0e0e0; border-radius: 8px; font-size: 14px; outline: none; transition: border-color 0.2s; background: #f9f9f9; }
.search-input:focus { border-color: #F02D00; background: #fff; }
.search-icon { position: absolute; right: 10px; top: 50%; transform: translateY(-50%); font-size: 14px; pointer-events: none; }
.header-actions { display: flex; gap: 10px; margin-left: auto; flex-shrink: 0; }
.btn-login { font-size: 14px; font-weight: 600; color: #171717; padding: 8px 16px; border: 1.5px solid #ddd; border-radius: 8px; transition: border-color 0.2s; }
.btn-login:hover { border-color: #171717; }
.btn-join, .btn-primary { font-size: 14px; font-weight: 700; color: #fff; background: #F02D00; padding: 8px 18px; border-radius: 8px; border: none; transition: background 0.2s; display: inline-flex; align-items: center; }
.btn-join:hover, .btn-primary:hover { background: #d42800; }

/* ── Layout ── */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 56px 0; }
.section:nth-child(odd) { }

/* ── Footer ── */
.footer { background: #171717; color: rgba(255,255,255,0.7); padding: 56px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 32px; margin-bottom: 40px; }
.footer-col-header { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: #fff; margin-bottom: 16px; cursor: default; display: flex; justify-content: space-between; align-items: center; }
.footer-toggle { display: none; }
.footer-links { display: flex; flex-direction: column; gap: 8px; }
.footer-links a { font-size: 13px; color: rgba(255,255,255,0.6); transition: color 0.15s; }
.footer-links a:hover { color: #fff; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; display: flex; flex-wrap: wrap; gap: 16px; align-items: center; justify-content: space-between; }
.footer-logo { font-size: 18px; font-weight: 900; color: #fff; }
.footer-logo span { color: #F02D00; }
.footer-legal { display: flex; flex-wrap: wrap; gap: 12px; }
.footer-legal a { font-size: 12px; color: rgba(255,255,255,0.5); }
.footer-legal a:hover { color: #fff; }
.footer-langs { display: flex; flex-wrap: wrap; gap: 8px; font-size: 12px; color: rgba(255,255,255,0.5); align-items: center; }
.footer-langs a { color: rgba(255,255,255,0.5); }
.footer-langs a:hover { color: #fff; }

/* ── Responsive ── */
@media (max-width: 768px) {
  .header-search { display: none; }
  .nav-links { gap: 0; }
  .nav-link { padding: 6px 8px; font-size: 13px; }
  .header-actions .btn-login { display: none; }
  .footer-toggle { display: block; }
  .footer-col-header { cursor: pointer; }
  .footer-collapsible { display: none; }
  .footer-collapsible.open { display: flex; }
  .footer-grid { grid-template-columns: 1fr; }
}
@media (max-width: 480px) {
  .header-inner { padding: 0 12px; gap: 12px; }
  .section { padding: 36px 0; }
  .container { padding: 0 14px; }
}

