            <svg class="social-icon" viewBox="0 0 24 24" fill="currentColor"><path d="M12.017 0C8.396 0 8.025.016 6.79.072 5.558.129 4.704.333 3.958.63c-.772.297-1.427.694-2.079 1.346C1.227 2.629.83 3.284.533 4.056.237 4.802.032 5.656-.025 6.89-.08 8.124-.097 8.495-.097 12.017s.016 3.892.072 5.127c.057 1.232.261 2.086.558 2.832.297.772.694 1.427 1.346 2.079.652.652 1.307 1.049 2.079 1.346.746.297 1.6.501 2.832.558C7.125 23.984 7.496 24 12.017 24s3.892-.016 5.127-.072c1.232-.057 2.086-.261 2.832-.558.772-.297 1.427-.694 2.079-1.346.652-.652 1.049-1.307 1.346-2.079.297-.746.501-1.6.558-2.832.056-1.235.072-1.606.072-5.127s-.016-3.892-.072-5.127c-.057-1.232-.261-2.086-.558-2.832-.297-.772-.694-1.427-1.346-2.079C21.83.83 21.175.433 20.403.136 19.657-.161 18.803-.366 17.569-.422 16.334-.48 15.963-.496 12.442-.496l-.425.496z"/></svg>
            Sign in with Apple
          </button>

          <div class="divider">or log in with email</div>

          <!-- Email/Password form -->
          <form id="loginForm" novalidate>
            <div class="form-group" id="emailGroup">
              <label class="form-label" for="email">Email</label>
              <div class="form-input-wrap">
                <input
                  type="email" id="email" name="email" class="form-input"
                  placeholder="your@email.com" autocomplete="email"
                  oninput="clearError('emailGroup')"
                />
              </div>
              <div class="form-error" id="emailError">Please enter a valid email address.</div>
            </div>

            <div class="form-group" id="passwordGroup">
              <label class="form-label" for="password">Password</label>
              <div class="form-input-wrap">
                <input
                  type="password" id="password" name="password" class="form-input"
                  placeholder="Enter your password" autocomplete="current-password"
                  style="padding-right:48px"
                  oninput="clearError('passwordGroup')"
                />
                <button class="toggle-pw" type="button" id="togglePw" onclick="togglePassword()" aria-label="Toggle password visibility">
                  <span id="pwIcon">👁</span>
                </button>
              </div>
              <div class="form-error" id="passwordError">Password is required.</div>
              <a href="#" class="forgot-link">Forgot your password?</a>
            </div>

            <button type="submit" class="btn-submit" id="submitBtn">
              Log in
            </button>

            <div class="form-success" id="formSuccess">
              <div class="success-icon">🎉</div>
              <h3>Welcome back!</h3>
              <p>Logging you in to your CreativeHub account...</p>
            </div>
          </form>

          <div class="signup-link">
            Don't have an account? <a href="plus.html">Join for Free</a>
          </div>
        </div>
      </div>
    </div>
  </main>

  <script>
    // Password visibility toggle
    function togglePassword() {
      const input = document.getElementById('password');
      const icon = document.getElementById('pwIcon');
      if (input.type === 'password') {
        input.type = 'text';
        icon.textContent = '🙈';
      } else {
        input.type = 'password';
        icon.textContent = '👁';
      }
    }

    // Clear error state
    function clearError(groupId) {
      document.getElementById(groupId).classList.remove('has-error');
    }

    // Form validation & submit
    document.getElementById('loginForm').addEventListener('submit', function(e) {
      e.preventDefault();
      let valid = true;

      const email = document.getElementById('email').value.trim();
      const password = document.getElementById('password').value;

      // Validate email
      const emailRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!email || !emailRe.test(email)) {
        document.getElementById('emailGroup').classList.add('has-error');
        document.getElementById('emailError').textContent = email
          ? 'Please enter a valid email address.'
          : 'Email is required.';
        valid = false;
      }

      // Validate password
      if (!password) {
        document.getElementById('passwordGroup').classList.add('has-error');
        valid = false;
      }

      if (valid) {
        const btn = document.getElementById('submitBtn');
        btn.disabled = true;
        btn.textContent = 'Logging in...';

        // Simulate login
        setTimeout(() => {
          btn.style.display = 'none';
          document.getElementById('formSuccess').style.display = 'block';
        }, 1200);
      }
    });

    // Social login
    function handleSocialLogin(provider) {
      const btn = event.currentTarget;
      btn.disabled = true;
      btn.textContent = `Connecting to ${provider}...`;
      setTimeout(() => {
        btn.textContent = `✓ Connected via ${provider}`;
        btn.style.background = '#22aa44';
      }, 1000);
    }
  </script>
</body>
</html>
